"""Set-7 acceptance fixtures from frozen specifications, independent of refs.

Only serializes literal answers or closed-form answers for simple limit cases.
Never imports, executes, or reads a reference or a submitted solution.
"""
from pathlib import Path
import shutil
ROOT=Path(__file__).resolve().parent
TASK=''
def put(path,value):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(value if isinstance(value,bytes) else value.encode('utf-8'))
def base(name,setup):
    p=ROOT/TASK/'cases'/name
    if p.exists(): shutil.rmtree(p)
    p.mkdir(parents=True)
    for filename,value in (setup or {}).items():
        if value is None: (p/'setup'/filename).mkdir(parents=True,exist_ok=True)
        else: put(p/'setup'/filename,value)
    return p
def files(p,args,stdin,out,code):
    put(p/'cmd',''.join(a+'\n' for a in args))
    if stdin: put(p/'stdin',stdin)
    put(p/'expected_stdout',out)
    if code is not None: put(p/'expected_exit',str(code)+'\n')
def case(name,args=(),stdin='',out='',code=0,setup=None): files(base(name,setup),args,stdin,out,code)
def multi(name,steps,setup=None):
    p=base(name,setup); manifest=[]
    for i,(args,stdin,out,code,*kill) in enumerate(steps,1):
        label=f'step-{i}'; manifest.append(label+(f' kill-after={kill[0]}' if kill else ''))
        files(p/label,args,stdin,out,None if kill else code)
    put(p/'steps','\n'.join(manifest)+'\n')
def errors(name,variants,code=2,setup=None): multi(name,[(a,'','',code) for a in variants],setup)
def bad(name,inputs,args=(),setup=None): multi(name,[(args,s,'',1) for s in inputs],setup)
def lines(items): return ''.join(x+'\n' for x in items)
def service(name,commands,responses,args=()): case(name,args,lines(commands),lines(responses))

